"""OpenAI Chat Completions 轻量封装。"""

from __future__ import annotations

import asyncio
import logging
import time
from collections.abc import AsyncIterator
from typing import Any

from openai import AsyncOpenAI

from aichat_sdk.config import OPENAI_API_KEY, OPENAI_BASE_URL, OPENAI_MODEL
from aichat_sdk.llm.mcp import get_default_chat_tools

logging.getLogger("httpx").setLevel(logging.WARNING)

logger = logging.getLogger("aichat_sdk")

_COMPRESS_SYSTEM_PROMPT = (
    "你是对话压缩器。把给出的历史对话压缩成一段摘要，供后续对话作为上下文使用。"
    "保留：用户告诉过助手的个人信息与偏好、明确的事实与数字、已做的决定、工具查询得到的关键结果、未完成的事项。"
    "去掉：寒暄、口语细节、重复内容。用第三人称陈述（用户/助手），500 字以内，直接输出摘要正文。"
)


class OpenAIClient:
    def __init__(
        self,
        model: str = OPENAI_MODEL,
        api_key: str = OPENAI_API_KEY,
        base_url: str = OPENAI_BASE_URL,
    ) -> None:
        self.model = model
        self.api_key = api_key
        self.base_url = base_url
        self.is_deepseek = "deepseek" in model.lower()

        # self.messages 里还挂了 time 等本地字段，OpenAI 拒绝 message 中的未知字段，发之前按白名单过滤
        self.message_fields = ("role", "content", "tool_calls", "tool_call_id", "name")
        # DeepSeek 开思考时要求同一轮里的 assistant 消息把 reasoning_content 原样回传，其他端点不认这个字段
        if self.is_deepseek:
            self.message_fields += ("reasoning_content",)

        self.compressor = ContextCompressor(self)

        self._client: AsyncOpenAI | None = None

    def _get_client(self) -> AsyncOpenAI:
        """按需创建客户端；openai 库把空 api_key 当缺凭据抛错，没配 key 时实例化 OpenAIClient 不能炸。"""
        if self._client is None:
            self._client = AsyncOpenAI(api_key=self.api_key, base_url=self.base_url)
        return self._client

    def get_final_messages(self, messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
        messages = self.compressor.compact(messages)
        return [{k: v for k, v in message.items() if k in self.message_fields} for message in messages]

    async def chat_stream(self, messages, thinking: bool = False) -> AsyncIterator[tuple[str, Any]]:
        """流式产出 ("text", str) / ("reasoning", str) / ("tool", dict) / ("usage", dict)。

        thinking=False 首包最快；但 deepseek 关思考后会把推理直接写进 content，调工具的中间轮尤其严重，
        所以工具循环里由调用方按需打开。
        """

        extra_body: dict[str, Any] = (
            {"thinking": {"type": "enabled" if thinking else "disabled"}}
            if self.is_deepseek
            else {"enable_thinking": thinking}
        )
        ctx_cursor = self.compressor.cursor
        kwargs: dict[str, Any] = {
            "model": self.model,
            "messages": self.get_final_messages(messages),
            "stream": True,
            "stream_options": {"include_usage": True},
            "tools": get_default_chat_tools(),
            "extra_body": extra_body,
        }

        t0 = time.perf_counter()
        stream = await self._get_client().chat.completions.create(**kwargs)

        current_tool_index: int | None = None
        current_tool: dict[str, str] | None = None
        final_usage: dict[str, Any] | None = None
        first_chunk = True
        first_chunk_latency = 0.0

        async for chunk in stream:
            if first_chunk and chunk.choices:
                delta = chunk.choices[0].delta
                if delta and (delta.content or delta.tool_calls):
                    first_chunk_latency = (time.perf_counter() - t0) * 1000
                    first_chunk = False

            if chunk.usage:
                usage = chunk.usage.model_dump() if hasattr(chunk.usage, "model_dump") else {}
                prompt = usage.get("prompt_tokens") or 0
                details = usage.get("prompt_tokens_details") or {}
                cached = details.get("cached_tokens") if isinstance(details, dict) else 0
                cached = cached or usage.get("prompt_cache_hit_tokens") or 0
                if not first_chunk:
                    usage["first_chunk_latency_ms"] = round(first_chunk_latency)
                # 标记本次请求用的压缩游标，maybe_compress 只认当前游标实测出的 usage
                usage["ctx_cursor"] = ctx_cursor
                final_usage = usage
                if prompt:
                    latency = f"first chunk latency: {first_chunk_latency:.0f}ms, " if not first_chunk else ""
                    logger.info(f"[llm] {latency}cache hit: {cached}/{prompt} ({cached / prompt * 100:.0f}%)")
                yield "usage", usage

            # 部分端点会发 choices 为空的 chunk（如带 usage 的收尾包、内容过滤包）
            if not chunk.choices:
                continue

            delta = chunk.choices[0].delta
            if not delta:
                continue
            reasoning = getattr(delta, "reasoning_content", None)
            if reasoning:
                yield "reasoning", reasoning
            if delta.content:
                yield "text", delta.content

            if delta.tool_calls:
                for tc in delta.tool_calls:
                    if tc.index != current_tool_index:
                        if current_tool is not None:
                            yield "tool", current_tool
                        current_tool_index = tc.index
                        current_tool = {"id": "", "name": "", "arguments": ""}
                    if current_tool is None:
                        continue

                    if tc.id:
                        current_tool["id"] = tc.id
                    fn = tc.function
                    if fn is None:
                        continue
                    if fn.name:
                        current_tool["name"] = fn.name
                    if fn.arguments:
                        current_tool["arguments"] += fn.arguments

        if current_tool is not None:
            yield "tool", current_tool

        # 本次调用结束、拿到实测 usage 就判断要不要压缩，不等下一条消息：
        # 压缩趁对话空闲期在后台跑，下轮进来时摘要大概率已就绪
        self.compressor.maybe_compress(messages, final_usage)


class ContextCompressor:
    """长对话上下文压缩：超限时后台把游标前的历史压成摘要，下次请求起替换原文。

    摘要覆盖 history[:cursor]，游标之后的消息原样发送；游标和摘要粘住不动、
    只在压缩完成换入时变一次，中间各轮前缀完全一致，prompt cache 只在换入那轮失效一次。
    只改发送副本，LlmAgent.messages 完整保留；状态跟随所属 OpenAIClient 绑定单个会话，勿跨会话复用。
    """

    # 上一轮 usage.total_tokens 超过这个值就触发压缩，防长对话 prompt 无限膨胀
    MAX_CONTEXT_TOKENS = 24_000

    def __init__(self, llm: OpenAIClient) -> None:
        self._llm = llm
        self.summary: str | None = None
        self.cursor = 0  # summary 覆盖的 history 下标上界（不含）
        self._task: asyncio.Task | None = None

    @property
    def compressing(self) -> bool:
        return self._task is not None and not self._task.done()

    @staticmethod
    def _split_history(messages: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
        head = messages[:1] if messages and messages[0].get("role") == "system" else []
        return head, messages[len(head) :]

    def compact(self, messages: list[dict[str, Any]]) -> list[dict[str, Any]]:
        """组装发送副本：system + 历史摘要 + 游标之后的原始消息；没压缩过就原样返回。

        游标落在 user 消息上，之后的消息完整成轮，不会出现丢了配对 tool_calls 的孤儿 tool 消息。
        """
        if not self.summary:
            return messages
        head, history = self._split_history(messages)
        summary_msg = {"role": "user", "content": f"（更早的对话已压缩，摘要如下，仅供参考）\n{self.summary}"}
        return head + [summary_msg] + history[self.cursor :]

    def maybe_compress(self, messages: list[dict[str, Any]], usage: dict[str, Any] | None) -> None:
        """每次 LLM 调用结束时带着本次实测 usage 调用：total_tokens 超限就后台压缩当前轮之前的历史。

        只认 ctx_cursor 等于当前游标的 usage：压缩若在本次调用期间换入，本次 usage 测的还是旧上下文，
        不作数，要等新上下文实测出一轮才可能再压，不会连环触发。压缩失败只记日志，下次超限再触发。
        """
        if self._task is not None and not self._task.done():
            return
        if not usage or usage.get("ctx_cursor", 0) != self.cursor:
            return
        total = usage.get("total_tokens") or 0
        if total <= self.MAX_CONTEXT_TOKENS:
            return

        _, history = self._split_history(messages)
        # 游标压到当前轮的 user 消息处，当前轮保持原文
        cursor = max((i for i, m in enumerate(history) if m.get("role") == "user"), default=None)
        if cursor is None or cursor <= self.cursor:
            return
        source = self._serialize(history[self.cursor : cursor])
        if self.summary:
            source = f"已有摘要：\n{self.summary}\n\n新增对话：\n{source}"
        logger.info(f"[llm] context {total} tokens > {self.MAX_CONTEXT_TOKENS}, compressing history[:{cursor}]")
        self._task = asyncio.create_task(self._compress(source, cursor))

    @staticmethod
    def _serialize(history: list[dict[str, Any]]) -> str:
        lines = []
        for m in history:
            role = m.get("role")
            if role == "user":
                lines.append(f"用户: {m.get('content')}")
            elif role == "assistant":
                if m.get("content"):
                    lines.append(f"助手: {m['content']}")
                for tc in m.get("tool_calls") or []:
                    fn = tc.get("function") or {}
                    lines.append(f"助手调用工具 {fn.get('name')}: {fn.get('arguments')}")
            elif role == "tool":
                lines.append(f"工具 {m.get('name')} 返回: {str(m.get('content'))[:1000]}")
        return "\n".join(lines)

    async def _compress(self, source: str, cursor: int) -> None:
        try:
            resp = await self._llm._get_client().chat.completions.create(
                model=self._llm.model,
                messages=[
                    {"role": "system", "content": _COMPRESS_SYSTEM_PROMPT},
                    {"role": "user", "content": source},
                ],
                extra_body=(
                    {"thinking": {"type": "disabled"}} if self._llm.is_deepseek else {"enable_thinking": False}
                ),
            )
            summary = (resp.choices[0].message.content or "").strip()
            if not summary:
                logger.warning("[llm] history compression returned empty summary, keep context as is")
                return
            self.summary = summary
            self.cursor = cursor
            logger.info(f"[llm] history[:{cursor}] compressed to {len(summary)} chars")
        except Exception:
            logger.exception("[llm] history compression failed")

