1441	function historyDuration(session) {
1442	  const seconds = Math.round((new Date(session.ended_at) - new Date(session.started_at)) / 1000);
1443	  if (!Number.isFinite(seconds) || seconds < 0) return "";
1444	  if (seconds < 60) return seconds + " 秒";
1445	  const minutes = Math.floor(seconds / 60);
1446	  if (minutes < 60) return minutes + " 分钟";
1447	  return Math.floor(minutes / 60) + " 小时" + (minutes % 60 ? " " + minutes % 60 + " 分钟" : "");
1448	}
