1450	function historyDay(value) {
1451	  const date = new Date(value);
1452	  if (Number.isNaN(date.getTime())) return "日期未知";
1453	  const today = new Date();
1454	  const yesterday = new Date(today);
1455	  yesterday.setDate(today.getDate() - 1);
1456	  if (date.toDateString() === today.toDateString()) return "今天";
1457	  if (date.toDateString() === yesterday.toDateString()) return "昨天";
1458	  return date.toLocaleDateString("zh-CN", {
1459	    month: "long", day: "numeric", ...(date.getFullYear() !== today.getFullYear() ? { year: "numeric" } : {}),
1460	  });
1461	}
