1517	async function loadHistoryDetail(sessionId, showDetail = true) {
1518	  if (historyDetailRequest) historyDetailRequest.abort();
1519	  const request = historyDetailRequest = new AbortController();
1520	  if (showDetail) {
1521	    $(".history-layout").classList.add("history-show-detail");
1522	    if (matchMedia("(max-width:720px)").matches) $("#history-back").focus();
1523	  }
1524	  for (const button of $("#history-list").querySelectorAll("button")) {
1525	    button.setAttribute("aria-pressed", String(button.dataset.sessionId === sessionId));
1526	  }
1527	  $("#history-meta").replaceChildren();
1528	  $("#history-messages").replaceChildren(historyPlaceholder("正在加载对话…"));
1529	  try {
1530	    const data = await historyFetch("/api/sessions/" + encodeURIComponent(sessionId), request);
1531	    if (request !== historyDetailRequest || !$("#history-dialog").open) return;
1532	    const session = data.session;
1533	    renderHistoryMeta(session);
1534	    const nodes = session.messages.map(renderHistoryMessage);
1535	    $("#history-messages").replaceChildren(...(nodes.length ? nodes : [historyPlaceholder("暂无消息")]));
1536	    $("#history-messages").scrollTop = 0;
1537	  } catch (error) {
1538	    if (error.name === "AbortError" || request !== historyDetailRequest) return;
1539	    $("#history-messages").replaceChildren(historyPlaceholder("暂时无法加载对话", error.message, true));
1540	  }
1541	}
