1543	async function loadHistory(offset = 0) {
1544	  if (historyListRequest) historyListRequest.abort();
1545	  if (historyDetailRequest) historyDetailRequest.abort();
1546	  const request = historyListRequest = new AbortController();
1547	  $(".history-layout").classList.remove("history-show-detail");
1548	  $("#history-list-label").textContent = historyQuery ? "搜索结果" : "全部会话";
1549	  $("#history-status").textContent = "查询中…";
1550	  $("#history-list").replaceChildren();
1551	  $("#history-list").setAttribute("aria-busy", "true");
1552	  $("#history-meta").replaceChildren();
1553	  $("#history-messages").replaceChildren(historyPlaceholder("选择一段对话", "在会话列表中选择，查看聊天记录"));
1554	  $("#history-prev").disabled = $("#history-next").disabled = true;
1555	  $("#history-page").textContent = "";
1556	  try {
1557	    const params = new URLSearchParams({ q: historyQuery, limit: HISTORY_PAGE_SIZE, offset });
1558	    const data = await historyFetch("/api/sessions?" + params, request);
1559	    if (request !== historyListRequest || !$("#history-dialog").open) return;
1560	    historyOffset = data.offset;
1561	    $("#history-status").textContent = data.total + " 个";
1562	    $("#history-page").textContent = data.total ? (Math.floor(data.offset / data.limit) + 1)
1563	      + " / " + Math.ceil(data.total / data.limit) : "";
1564	    $("#history-prev").disabled = data.offset === 0;
1565	    $("#history-next").disabled = data.offset + data.sessions.length >= data.total;
1566	    const nodes = [];
1567	    let lastDay = null;
1568	    for (const session of data.sessions) {
1569	      const day = historyDay(session.started_at);
1570	      if (day !== lastDay) nodes.push(el("div", "history-date", day));
1571	      lastDay = day;
1572	      const button = el("button", "history-item");
1573	      button.type = "button";
1574	      button.dataset.sessionId = session.id;
1575	      button.setAttribute("aria-pressed", "false");
1576	      const content = el("span", "history-item-content");
1577	      content.append(el("span", "history-preview", session.preview || "未命名会话"));
1578	      const clock = new Date(session.started_at).toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit", hour12: false });
1579	      content.append(el("span", "history-item-meta", clock + " · " + session.message_count + " 条消息"));
1580	      button.append(historyIcon(), content);
1581	      button.addEventListener("click", () => loadHistoryDetail(session.id));
1582	      nodes.push(button);
1583	    }
1584	    $("#history-list").replaceChildren(...(nodes.length ? nodes : [historyPlaceholder(historyQuery
1585	      ? "没有找到相关对话" : "还没有历史会话", historyQuery ? "换一个关键词，或清空搜索再试试" : "会话结束后，记录会保存在这里")]));
1586	    if (data.sessions.length) loadHistoryDetail(data.sessions[0].id, false);
1587	  } catch (error) {
1588	    if (error.name === "AbortError" || request !== historyListRequest) return;
1589	    $("#history-status").textContent = "加载失败";
1590	    $("#history-list").replaceChildren(historyPlaceholder("暂时无法加载", error.message, true));
1591	  } finally {
1592	    if (request === historyListRequest) $("#history-list").setAttribute("aria-busy", "false");
1593	  }
1594	}
