// ---------------- AI 日记与记忆 ----------------

const DIARY_PAGE_SIZE = 20;
let diaryOffset = 0;
let diaryRequest = null;
let memoryDirty = false;   // 记忆框有没保存的改动时，刷新不覆盖它
let memorySaving = false;
let lastDiaryFinishedAt = "";
let diaryRequestedFrom = null;  // 点「立即整理」时的 finished_at；它变了说明这一轮已经结束

function diaryDateLabel(value) {  // "YYYY-MM-DD" 是本地日期，按年月日构造，避免 new Date(str) 当成 UTC 零点
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  if (Number.isNaN(date.getTime())) return value;
  const today = new Date();
  const yesterday = new Date(today.getFullYear(), today.getMonth(), today.getDate() - 1);
  const weekday = "星期" + "日一二三四五六"[date.getDay()];
  if (date.toDateString() === today.toDateString()) return "今天 · " + weekday;
  if (date.toDateString() === yesterday.toDateString()) return "昨天 · " + weekday;
  return date.toLocaleDateString("zh-CN", {
    month: "long", day: "numeric", ...(year !== today.getFullYear() ? { year: "numeric" } : {}),
  }) + " " + weekday;
}

function diaryClock(value) {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toLocaleString("zh-CN", {
    month: "numeric", day: "numeric", hour: "2-digit", minute: "2-digit", hour12: false,
  });
}

function diaryBusy() {
  const state = fullState.diary || {};
  return Boolean(state.running) || (diaryRequestedFrom !== null && (state.finished_at || "") === diaryRequestedFrom);
}

function renderDiaryStatus() {
  const state = fullState.diary || {};
  const busy = diaryBusy();
  $("#diary-run").disabled = busy;
  let text = "每小时自动整理一次已结束的会话";
  let kind = "";
  if (busy) {
    text = "正在整理日记…";
  } else if (state.error) {
    text = "上次整理失败：" + state.error;
    kind = "err";
  } else if (state.finished_at) {
    const clock = new Date(state.finished_at).toLocaleTimeString("zh-CN", { hour: "2-digit", minute: "2-digit", hour12: false });
    const dates = (state.dates || []).map((value) => {
      const [, month, day] = value.split("-").map(Number);
      return month + "月" + day + "日";
    });
    text = clock + " 整理完成，" + (dates.length ? "更新了 " + dates.join("、") + " 的日记" : "没有新的对话");
    if (state.pending) text += "；还有 " + state.pending + " 个会话待整理";
    if (state.skipped) text += "，其中 " + state.skipped + " 个被模型拒绝，下一轮重试";
    kind = "ok";
  }
  $("#diary-status").textContent = text;
  $("#diary-status").className = "note " + kind;
}

function memoryNote(text, ok) {
  $("#memory-note").textContent = text;
  $("#memory-note").className = "note " + (ok ? "ok" : "err");
}

function renderMemory(memory) {
  $("#memory-text").value = memory.content || "";
  const source = memory.source === "manual" ? (memory.content ? "手动修改" : "已清空") : "自动整理";
  $("#memory-meta").textContent = memory.updated_at ? source + " · " + diaryClock(memory.updated_at) : "";
  memoryDirty = false;
  $("#memory-save").disabled = true;
}

async function loadMemory() {
  try {
    const res = await fetch("/api/memory", { cache: "no-store" });
    const data = await res.json();
    if (!res.ok || !data.ok) throw new Error(data.error || "读取失败");
    if (!memoryDirty) renderMemory(data.memory);  // 加载期间开始编辑的话，保留编辑内容
  } catch (error) {
    memoryNote("读取记忆失败：" + (error.message || error), false);
  }
}

async function saveMemory(content, success) {
  if (memorySaving) return;
  memorySaving = true;
  $("#memory-save").disabled = $("#memory-clear").disabled = true;
  memoryNote("正在保存…", true);
  try {
    const res = await fetch("/api/memory", {
      method: "PUT", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ content }),
    });
    const data = await res.json();
    if (!res.ok || !data.ok) throw new Error(data.error || "保存失败");
    renderMemory(data.memory);
    memoryNote(success, true);
  } catch (error) {
    memoryNote(error.message || String(error), false);
    $("#memory-save").disabled = !memoryDirty;
  } finally {
    memorySaving = false;
    $("#memory-clear").disabled = false;
  }
}

function renderDiaryEntry(entry) {
  const node = el("article", "diary-entry");
  const head = el("div", "head");
  head.append(
    el("span", "date", diaryDateLabel(entry.date)),
    el("span", "meta", entry.session_count + " 次对话 · 更新于 " + diaryClock(entry.updated_at)),
  );
  node.append(head, el("div", "body", entry.content));
  return node;
}

async function loadDiaries(offset = 0) {
  if (diaryRequest) diaryRequest.abort();
  const request = diaryRequest = new AbortController();
  if (!offset) $("#diary-list").replaceChildren(el("div", "empty", "正在加载…"));
  $("#diary-more").disabled = true;
  try {
    const params = new URLSearchParams({ limit: DIARY_PAGE_SIZE, offset });
    const res = await fetch("/api/diaries?" + params, { signal: request.signal, cache: "no-store" });
    const data = await res.json();
    if (!res.ok || !data.ok) throw new Error(data.error || "查询失败，请重试");
    if (request !== diaryRequest) return;
    const nodes = data.diaries.map(renderDiaryEntry);
    if (offset) $("#diary-list").append(...nodes);
    else $("#diary-list").replaceChildren(...(nodes.length ? nodes
      : [el("div", "empty", "还没有日记。会话结束后每小时自动整理，也可以点「立即整理」。")]));
    diaryOffset = offset + data.diaries.length;
    $("#diary-more").hidden = diaryOffset >= data.total;
  } catch (error) {
    if (error.name === "AbortError" || request !== diaryRequest) return;
    const note = el("div", "empty err", "暂时无法加载日记：" + (error.message || error));
    if (offset) $("#diary-list").append(note);
    else $("#diary-list").replaceChildren(note);
  } finally {
    if (request === diaryRequest) {
      diaryRequest = null;
      $("#diary-more").disabled = false;
    }
  }
}

async function runDiary() {
  $("#diary-run").disabled = true;
  try {
    const res = await fetch("/api/diaries/update", { method: "POST" });
    const data = await res.json();
    if (!res.ok || !data.ok) throw new Error(data.error || "启动失败");
    diaryRequestedFrom = data.diary.finished_at || "";
    renderDiaryStatus();
  } catch (error) {
    $("#diary-status").textContent = error.message || String(error);
    $("#diary-status").className = "note err";
    $("#diary-run").disabled = diaryBusy();
  }
}

function refreshDiary() {  // SSE 每帧调用：一轮整理结束（finished_at 变了）就重载日记，记忆框没改动时一并重载
  const finishedAt = fullState.diary?.finished_at || "";
  if (finishedAt !== lastDiaryFinishedAt) {
    lastDiaryFinishedAt = finishedAt;
    diaryRequestedFrom = null;
    loadDiaries();
    if (!memoryDirty) loadMemory();
  }
  renderDiaryStatus();
}

$("#diary-open").addEventListener("click", () => {
  $("#diary-dialog").showModal();
  lastDiaryFinishedAt = fullState.diary?.finished_at || "";
  memoryNote("", true);
  renderDiaryStatus();
  if (!memoryDirty) loadMemory();
  loadDiaries();
});
$("#diary-close").addEventListener("click", () => $("#diary-dialog").close());
$("#diary-dialog").addEventListener("close", () => {
  if (diaryRequest) diaryRequest.abort();
});
$("#memory-text").addEventListener("input", () => {
  memoryDirty = true;
  $("#memory-save").disabled = memorySaving;
});
$("#memory-save").addEventListener("click", () => saveMemory($("#memory-text").value, "已保存，下次会话生效"));
$("#memory-clear").addEventListener("click", () => {
  if (confirm("清空全部记忆？助手从下次会话开始不再记得这些内容。")) saveMemory("", "已清空，下次会话生效");
});
$("#diary-run").addEventListener("click", runDiary);
$("#diary-more").addEventListener("click", () => loadDiaries(diaryOffset));

if ($("#voiceprint-dialog").open) renderVoiceprints();
if ($("#diary-dialog").open) refreshDiary();
if (busy) return;

